def div_by_exactly_one(num: int, a: int, b: int) -> bool:
    # True only when exactly one of a, b divides num (XOR).
    return (num % a == 0) != (num % b == 0)

def convert_date(date: str) -> str:
    mm, dd, yy = date.split("-")
    return f"{yy}-{dd}-{mm}"

def increment_value_with_max_limit(d: dict, key, inc: int, limit: int) -> None:
    # Increment in place, capping the result at limit.
    d[key] = min(d[key] + inc, limit)

def last_uppercase_word(sentence: str):
    result = None
    for word in sentence.split(" "):
        if word and word[0].isupper():
            result = word  # keep the latest match
    return result

n = int(input())
lines = [input() for _ in range(n)]

# Swap each consecutive pair; a lone last line stays in place.
out = []
for i in range(0, n, 2):
    if i + 1 < n:
        out.append(lines[i + 1])
        out.append(lines[i])
    else:
        out.append(lines[i])

# Reverse every odd-numbered line of the output (positions 1, 3, 5 -> indices 0, 2, 4).
for idx, line in enumerate(out):
    print(line[::-1] if idx % 2 == 0 else line)

def word_filters(words: list, criteria: str):
    vowels = set("aeiou")

    def is_sorted(word):
        w = word.lower()
        return list(w) == sorted(w)

    if criteria == "continuous":
        return [w for w in words if w.lower().endswith("ing")]
    elif criteria == "vowel_rich":
        return [w for w in words if sum(c in vowels for c in w.lower()) > 5]
    elif criteria == "consonant_rich":
        return [w for w in words
                if sum(c.isalpha() and c not in vowels for c in w.lower()) > 5]
    elif criteria == "sorted":
        return [w for w in words if is_sorted(w)]
    else:
        return None

